function drawFighter(f,ghost){if(!sprites[f.char])return;ctx.save();ctx.translate(f.x,f.y);const lean=clamp((f.mx||0)/1800,-.22,.22);ctx.rotate(lean);if(f.attack>0&&!ghost)ctx.rotate(Math.sin(f.attack*18)*.08);ctx.fillStyle='#0005';ctx.beginPath();ctx.ellipse(0,32,38,11,0,0,7);ctx.fill();ctx.strokeStyle=colors[f.id];ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,32,41,14,0,0,7);ctx.stroke();ctx.shadowColor=f.slow>0?'#6aeaff':colors[f.id];ctx.shadowBlur=f.hit>0?25:8;ctx.globalAlpha*=f.hp<=0?.3:1;ctx.drawImage(sprites[f.char],-46,-109,92,138);ctx.shadowBlur=0;if(f.char===9&&!ghost){ctx.save();ctx.strokeStyle=f.invincible>0?'#fff6c4':colors[f.id];ctx.lineWidth=f.invincible>0?4:2;ctx.globalAlpha=f.invincible>0?.9:evasionRate(f);ctx.beginPath();ctx.ellipse(0,-35,58,80,0,0,7);ctx.stroke();ctx.restore();ctx.font='bold 10px sans-serif';ctx.textAlign='center';ctx.fillStyle='#ffd0e3';ctx.fillText(f.invincible>0?'無敵':'EVA '+Math.round(evasionRate(f)*100)+'%',0,-122)}if(isSilenced(f)&&!ghost){ctx.fillStyle='#b0e5ff';ctx.font='bold 11px sans-serif';ctx.textAlign='center';ctx.fillText('技封印',0,-145)}if(f.grabbedBy>=0&&!ghost){ctx.font='bold 12px sans-serif';ctx.textAlign='center';ctx.fillStyle='#ffd0e3';ctx.fillText('拘束',0,-130)}if(f.char===8&&!ghost){ctx.save();ctx.strokeStyle=colors[f.id];ctx.globalAlpha*=f.reflectBoost>0?.9:.35;ctx.lineWidth=f.reflectBoost>0?4:2;ctx.beginPath();ctx.ellipse(0,-30,55,75,0,0,7);ctx.stroke();ctx.beginPath();ctx.moveTo(-32,-80);ctx.lineTo(32,20);ctx.stroke();ctx.restore()}if(f.char===6&&!ghost){ctx.save();ctx.strokeStyle='#b5ffe4';ctx.globalAlpha*=f.regenBoost>0?.85:.3;ctx.lineWidth=f.regenBoost>0?3:1.5;ctx.beginPath();ctx.ellipse(0,10,48,18,0,0,7);ctx.stroke();if(f.regenBoost>0){for(let n=0;n<4;n++){const a=n*Math.PI/2+elapsed,x=Math.cos(a)*48,y=-((elapsed*30+n*23)%120);ctx.beginPath();ctx.moveTo(x-5,y);ctx.lineTo(x+5,y);ctx.moveTo(x,y-5);ctx.lineTo(x,y+5);ctx.stroke()}}ctx.restore()}if(f.poisonTime>0){ctx.strokeStyle="#a8ee7c";ctx.fillStyle="#a8ee7c";ctx.lineWidth=2;ctx.globalAlpha*=.8;ctx.beginPath();ctx.ellipse(0,-25,55,60,0,0,7);ctx.stroke();for(let n=0;n<f.poisonStacks;n++){const a=n*1.3+elapsed*1.2;ctx.beginPath();ctx.arc(Math.cos(a)*49,Math.sin(a)*40-25,3,0,7);ctx.fill()}ctx.globalAlpha/= .8}if(f.bind>0){ctx.strokeStyle="#f0b5dd";ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(0,-25,51,32,.5,0,7);ctx.stroke()}if(f.char===4&&!ghost){ctx.fillStyle="#3c3440";ctx.fillRect(-33,-126,66,5);ctx.fillStyle=colors[f.id];ctx.fillRect(-33,-126,66*f.charge,5);ctx.font="9px sans-serif";ctx.textAlign="center";ctx.fillText("CHARGE",0,-132)}if(f.char===2){ctx.save();ctx.strokeStyle=f.guard>0?'#e7efff':colors[f.id];ctx.globalAlpha*=f.guard>0?.8:.35;ctx.lineWidth=f.guard>0?4:2;ctx.beginPath();for(let j=0;j<6;j++){const a=j*Math.PI/3;ctx.lineTo(Math.cos(a)*(f.guard>0?64:48),Math.sin(a)*(f.guard>0?72:55)-30)}ctx.closePath();ctx.stroke();ctx.restore()}if(f.frozen>0){ctx.strokeStyle='#b6f6ff';ctx.lineWidth=3;ctx.strokeRect(-47,-114,94,151)}if(f.burn>0){ctx.strokeStyle='#ff9b60';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,-30,61,0,7);ctx.stroke()}if(!ghost){ctx.font='bold 12px sans-serif';ctx.textAlign='center';ctx.fillStyle=colors[f.id];ctx.fillText(nameOf(f)+' · P'+(f.id+1),0,55);if(f.slow>0){ctx.strokeStyle='#b3f7ff';ctx.lineWidth=2;ctx.strokeRect(-37,-42,74,60);ctx.font='10px sans-serif';ctx.fillText('SLOW',0,-135)}}ctx.restore()}
function frame(t){const raw=Math.min((t-last)/1000||0,.04);last=t;const dt=raw*speed;if(running&&!paused){for(let n=0;n<Math.ceil(dt/.015);n++){if(running)step(dt/Math.ceil(dt/.015))}}if(!paused){for(const q of fx){q.life-=dt;if(q.ring)q.r+=340*dt;else if(q.vx!==undefined){q.x+=q.vx*dt;q.y+=q.vy*dt}}fx=fx.filter(q=>q.life>0);for(const l of labels){l.life-=dt;l.y-=35*dt}labels=labels.filter(l=>l.life>0);for(const tr of trails)tr.life-=dt;trails=trails.filter(tr=>tr.life>0);shake*=.85;cutTimer-=dt;if(cutTimer<=0)$('skillcut').classList.remove('active','overflow');callTimer-=dt;if(callTimer<=0)$('callout').classList.remove('show')}draw();requestAnimationFrame(frame)}
$('start').onclick=start;$('reset').onclick=reset;$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'再開':'一時停止';$('status').textContent=paused?'PAUSED':'FIGHTING'};$('speed').onchange=e=>setPlaybackSpeed(+e.target.value);$('sound').onclick=()=>{sound=!sound;$('sound').textContent='音 '+(sound?'ON':'OFF');$('sound').setAttribute('aria-pressed',sound);if(sound)beep(440)};document.addEventListener('visibilitychange',()=>{if(document.hidden&&running&&!paused)$('pause').click()});requestAnimationFrame(frame);

