function setPlaybackSpeed(value){const index=PLAYBACK_SPEEDS.indexOf(value);if(index<0)return false;speed=value;$('speed').value=String(value);$('speed-current').textContent=value+'×';$('speed-down').disabled=index===0;$('speed-up').disabled=index===PLAYBACK_SPEEDS.length-1;$('speed-down').title=index>0?PLAYBACK_SPEEDS[index-1]+'倍へ':'最低速度';$('speed-up').title=index<PLAYBACK_SPEEDS.length-1?PLAYBACK_SPEEDS[index+1]+'倍へ':'最高速度';return true}
$('speed-down').onclick=()=>setPlaybackSpeed(PLAYBACK_SPEEDS[Math.max(0,PLAYBACK_SPEEDS.indexOf(speed)-1)]);
$('speed-up').onclick=()=>setPlaybackSpeed(PLAYBACK_SPEEDS[Math.min(PLAYBACK_SPEEDS.length-1,PLAYBACK_SPEEDS.indexOf(speed)+1)]);
setPlaybackSpeed(speed);
